create table if not exists public.coach_session_objectives (
 id uuid primary key default gen_random_uuid(),
 coach_id uuid not null references public.profiles(id) on delete cascade,
 objective_id text not null,
 theme text not null,
 label text not null,
 profile text not null,
 criteria text[] not null default '{}',
 intent text not null,
 success text not null,
 display_order integer not null default 0,
 active boolean not null default true,
 created_at timestamptz not null default now(),
 updated_at timestamptz not null default now(),
 unique(coach_id,objective_id)
);
create index if not exists coach_session_objectives_owner_theme_idx on public.coach_session_objectives(coach_id,theme,display_order);
alter table public.coach_session_objectives enable row level security;
revoke all on public.coach_session_objectives from anon;
grant select,insert,update,delete on public.coach_session_objectives to authenticated;
drop policy if exists "Coach reads own session objectives" on public.coach_session_objectives;
create policy "Coach reads own session objectives" on public.coach_session_objectives for select to authenticated using(coach_id=(select auth.uid()));
drop policy if exists "Coach inserts own session objectives" on public.coach_session_objectives;
create policy "Coach inserts own session objectives" on public.coach_session_objectives for insert to authenticated with check(coach_id=(select auth.uid()) and exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role='coach'));
drop policy if exists "Coach updates own session objectives" on public.coach_session_objectives;
create policy "Coach updates own session objectives" on public.coach_session_objectives for update to authenticated using(coach_id=(select auth.uid())) with check(coach_id=(select auth.uid()) and exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role='coach'));
drop policy if exists "Coach deletes own session objectives" on public.coach_session_objectives;
create policy "Coach deletes own session objectives" on public.coach_session_objectives for delete to authenticated using(coach_id=(select auth.uid()) and exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role='coach'));
insert into public.coach_session_objectives(coach_id,objective_id,theme,label,profile,criteria,intent,success,display_order)
select coach.id,seed.objective_id,seed.theme,seed.label,seed.profile,seed.criteria,seed.intent,seed.success,seed.display_order
from public.profiles coach cross join (values
('cd-early','Coup droit','Prendre la balle tôt sur la montée','early',array['Prise de balle trop basse','Plan de frappe trop tardif','Préparation de raquette tardive','Orientation des épaules']::text[],'Prendre du temps à l’adversaire en frappant en phase montante, devant soi et en équilibre.','Prendre tôt au moins 7 balles sur 10 et conserver une trajectoire profonde.',1),
('cd-line','Coup droit','Attaquer long de ligne sur balle courte','line',array['Accélération de la tête de raquette','Stabilité à l’impact','Transfert du poids du corps','Adaptation de la distance à la balle']::text[],'Reconnaître une balle courte, avancer et changer la direction vers le long de ligne avec une marge.','Réussir 6 attaques sur 10 dans le couloir long de ligne, avec replacement vers l’avant.',2),
('cd-open','Coup droit','Déplacer l’adversaire et jouer dans la zone libre','open',array['Variation des effets','Variation des trajectoires et des hauteurs','Régularité dans les différentes zones du court']::text[],'Fixer l’adversaire dans une zone puis exploiter l’espace qu’il vient de libérer.','Créer et exploiter une zone libre sur 6 points sur 10.',3),
('cd-insideout','Coup droit','Se décaler autour du revers et jouer inside-out','insideout',array['Adaptation de la distance à la balle','Orientation des épaules','Stabilité à l’impact','Transfert du poids du corps']::text[],'Construire le décalage, jouer coup droit inside-out puis récupérer pour couvrir le coup suivant.','Réussir 6 séquences décalage–inside-out–replacement sur 8.',4),
('cd-depth','Coup droit','Construire une diagonale profonde et varier les effets','depth',array['Régularité dans les différentes zones du court','Variation des effets','Variation des trajectoires et des hauteurs']::text[],'Installer une balle longue et lourde, puis modifier hauteur et effet sans perdre la profondeur.','Enchaîner 8 balles sur 10 dans la zone profonde avec deux trajectoires distinctes.',5),
('rev-early','Revers','Prendre le revers tôt et devant soi','early',array['Prise de balle montante','Prise de balle tôt','Plan de frappe devant le corps','Préparation précoce de la raquette']::text[],'Intercepter la balle en phase montante pour réduire le temps de réaction adverse.','Prendre tôt 7 balles sur 10 sans déséquilibre.',6),
('rev-cross','Revers','Tenir une diagonale longue et régulière','depth',array['Régularité','Gestion de la hauteur de balle','Stabilité des appuis','Qualité de centrage']::text[],'Installer une diagonale solide, longue et haute avec une marge au-dessus du filet.','Enchaîner 8 revers sur 10 dans la zone longue croisée.',7),
('rev-line','Revers','Changer long de ligne sur balle favorable','line',array['Plan de frappe devant le corps','Transfert du poids du corps','Orientation des épaules']::text[],'Construire en diagonale puis changer long de ligne uniquement sur une balle équilibrée.','Choisir le bon moment et réussir 6 changements sur 10.',8),
('rev-slice','Revers','Utiliser le slice pour varier et monter','transition',array['Variation des effets : lift, balle à plat, slice','Variation des trajectoires et des hauteurs','Finition du geste']::text[],'Changer le rythme avec un slice bas et long, puis avancer lorsque la balle adverse devient courte.','Produire 6 slices bas et profonds sur 10 et monter sur une balle favorable.',9),
('rev-onehand','Revers','Stabiliser le revers à une main en avançant','early',array['Extension du bras directeur','Maintien du bras non directeur en accompagnement','Stabilité du poignet à l’impact','Plan de frappe devant le corps']::text[],'Coordonner l’extension du bras directeur et l’accompagnement du bras libre pour un contact devant.','Réaliser 7 contacts sur 10 devant le corps avec une trajectoire maîtrisée.',10),
('srv-first','Service','Première balle : placer pour préparer le coup suivant','serveplus',array['Rythme de la préparation et de la frappe','Coude haut']::text[],'Utiliser la zone du service pour obtenir une réponse prévisible et organiser le service + 1.','Atteindre la zone annoncée 6 fois sur 10 et jouer le coup + 1 avec intention.',11),
('srv-second','Service','Deuxième balle : sécurité, hauteur et rotation','second',array['Rythme de la préparation et de la frappe','Coude haut','Lancer trop devant','Lancer trop derrière']::text[],'Sécuriser la deuxième balle par une trajectoire bombée, de la rotation et une cible choisie.','Réussir 8 deuxièmes balles sur 10 dans le carré visé avec hauteur et rotation.',12),
('srv-slice','Service','Service slicé pour sortir le relanceur du court','serveplus',array['Rythme de la préparation et de la frappe','Lancer trop loin sur le côté']::text[],'Créer un angle extérieur au service pour libérer le côté opposé au coup suivant.','Atteindre la zone extérieure 6 fois sur 10 et exploiter l’espace au coup suivant.',13),
('srv-body','Service','Service au corps et première frappe dans l’espace','serveplus',array['Coude haut','Rythme de la préparation et de la frappe']::text[],'Gêner le placement du relanceur avec un service au corps puis jouer dans l’espace créé.','Créer une réponse courte ou centrale exploitable sur 6 points sur 10.',14),
('ret-first','Retour de service','Première balle : bloquer et remettre profond','returnfirst',array['Blocage efficace','Préparation courte et compacte','Réactivité','Reprise d’appuis synchronisée','Contrôle de la profondeur']::text[],'Neutraliser la vitesse du premier service avec un retour compact et profond.','Remettre 7 premières balles sur 10 en jeu avec de la profondeur.',15),
('ret-second','Retour de service','Deuxième balle : prendre l’initiative','returnsecond',array['Attaque de la deuxième balle','Prise d’initiative','Prise de balle devant et précoce','Utilisation des angles']::text[],'Avancer dans le court et prendre l’initiative sur une deuxième balle moins rapide.','Prendre l’initiative sur 6 retours sur 10 sans précipitation.',16),
('ret-direction','Retour de service','Varier retour croisé, centre et long de ligne','returnsecond',array['Variation des zones','Contrôle de la profondeur','Lecture de la trajectoire']::text[],'Choisir la direction du retour en fonction du service et du placement du serveur.','Faire le bon choix de zone sur 7 retours sur 10.',17),
('ret-plusone','Retour de service','Retour + première frappe pour reprendre le terrain','returnfirst',array['Prise de balle devant soi','Contrôle de la profondeur','Régularité']::text[],'Ne pas s’arrêter au retour : se replacer et construire la frappe suivante.','Réaliser 6 séquences retour + replacement + frappe suivante sur 8.',18),
('vol-approach','Volée','Volée d’approche puis volée de finition','transition',array['Contact devant le corps','Déplacement efficace vers l’avant','Contrôle de la profondeur','Jeu de jambes adapté à la trajectoire']::text[],'Garder l’avantage en avançant progressivement et en préparant la volée de finition.','Réussir 6 enchaînements approche–finition sur 8.',19),
('vol-finish','Volée','Finir dans la zone libre du défenseur','volleyfinish',array['Contrôle de la direction','Finition courte et maîtrisée','Prise de balle tôt','Orientation du tamis']::text[],'Lire la position du défenseur et finir dans l’espace plutôt que frapper systématiquement fort.','Placer 7 volées de finition sur 10 hors de portée du défenseur.',20),
('vol-low','Volée','Volée basse : contrôler et garder la ligne','volleylow',array['Absorption de la vitesse de la balle','Équilibre dynamique','Contrôle de la profondeur']::text[],'Neutraliser une balle basse sans ouvrir le tamis ni subir le rebond.','Remettre 7 volées basses sur 10 au-delà de la ligne de service.',21),
('vol-counter','Volée','Volée à contretemps après déplacement adverse','volleyfinish',array['Réactivité à la volée','Jeu de jambes adapté à la trajectoire','Prise de balle tôt']::text[],'Profiter du déplacement ou du déséquilibre adverse pour intercepter tôt et finir.','Gagner 6 situations de volée à contretemps sur 10.',22),
('move-split','Jeu de jambes/déplacements','Synchroniser la reprise d’appuis avec la frappe adverse','movement',array['Reprise d’appuis trop tardive','Qualité de la reprise d’appuis','Coordination des déplacements et de la frappe']::text[],'Déclencher le déplacement au bon moment pour démarrer équilibré.','Démarrer dans le bon timing sur 8 signaux sur 10.',23),
('move-lateral','Jeu de jambes/déplacements','Défendre droite-gauche et revenir sur la pastille','movement',array['Rapidité dans les changements de direction','Déplacement latéral efficace','Accélération sur les premiers appuis']::text[],'Couvrir deux côtés en limitant le temps passé hors de la zone de replacement.','Enchaîner 5 déplacements droite-gauche avec frappe équilibrée.',24),
('move-depth','Jeu de jambes/déplacements','Déplacements avant-arrière : amortie, lob et replacement','movement',array['Déplacement efficace vers l’avant','Déplacement vers l’arrière maîtrisé','Gestion des petits pas d’ajustement']::text[],'Gérer les changements de profondeur et choisir la réponse adaptée à la trajectoire.','Réussir 7 déplacements avant-arrière sur 10 avec replacement.',25),
('move-recover','Jeu de jambes/déplacements','Replacement après frappe et couverture du terrain','movement',array['Replacement rapide','Repositionnement après la frappe','Utilisation des appuis en déplacement']::text[],'Retrouver une position de couverture adaptée à la direction et à la qualité de sa frappe.','Être replacé avant la frappe adverse sur 8 échanges sur 10.',26),
('tac-open','Tactique','Déplacer l’adversaire pour jouer dans la zone libre','open',array['Exploitation des espaces libres','Construction du point','Utilisation des angles']::text[],'Construire un déplacement adverse puis exploiter l’espace libre.','Créer un espace puis le jouer sur 6 points sur 10.',27),
('tac-dno','Tactique','Reconnaître les balles défensives, neutres et offensives','decision',array['Choix de zone inadapté','Prise d’initiative insuffisante','Utilisation des zones de sécurité']::text[],'Adapter la réponse à la qualité de balle : défendre, neutraliser ou attaquer.','Faire le bon choix sur 8 situations sur 10.',28),
('tac-length','Tactique','Construire par la longueur avant de changer de direction','depth',array['Contrôle de la profondeur','Construction du point','Variation des longueurs']::text[],'Repousser l’adversaire avec des balles profondes avant de créer une ouverture.','Obtenir une balle courte après une séquence profonde sur 6 échanges sur 10.',29),
('tac-pattern','Tactique','Construire un schéma service + 1 ou retour + 1','serveplus',array['Prise d’initiative','Variation des zones','Adaptation du jeu au profil de l’adversaire']::text[],'Associer une première intention à une frappe suivante préparée et l’adapter à la réponse réelle.','Exécuter le schéma choisi sur 6 points sur 10.',30),
('phy-speed','Physique','Rapidité des premiers appuis et réaction','movement',array['Accélération sur les premiers appuis','Vitesse de réaction','Réactivité au démarrage']::text[],'Améliorer le premier pas vers la balle et la capacité à répéter les démarrages.','Réagir correctement à 8 départs sur 10 sans perdre l’équilibre.',31),
('phy-repeat','Physique','Répéter les efforts intenses avec qualité de frappe','movement',array['Capacité à répéter les efforts intenses','Maintien de l’intensité physique','Résistance à la fatigue']::text[],'Maintenir la qualité technique et la prise de décision malgré l’accumulation des efforts.','Maintenir le critère technique sur 3 séries successives.',32),
('phy-coord','Physique','Coordination œil-main et ajustement des appuis','movement',array['Coordination œil-main','Coordination générale','Stabilité des appuis']::text[],'Améliorer l’ajustement du corps à la trajectoire avant le contact.','Réaliser 8 frappes équilibrées sur 10 après déplacement.',33),
('phy-power','Physique','Explosivité et puissance utile dans les frappes','line',array['Explosivité des jambes','Puissance des frappes','Accélération insuffisante']::text[],'Transférer la poussée des jambes et la coordination vers une frappe efficace.','Produire 6 frappes offensives profondes sur 10 après engagement des appuis.',34),
('men-routine','Mental','Installer une routine stable entre les points','decision',array['Respect des routines entre les points','Manque de respect des routines']::text[],'Retrouver une organisation simple entre chaque point pour choisir une intention claire.','Routine complète sur 8 points sur 10.',35),
('men-pressure','Mental','Jouer les points importants avec un plan clair','decision',array['Capacité à jouer les points importants','Difficulté à jouer les points importants','Prise de décision lucide sous pression']::text[],'Maintenir une intention tactique et une décision cohérente sous pression du score.','Prendre une décision cohérente sur 7 points importants sur 10.',36),
('men-reset','Mental','Se recentrer après une erreur ou un point perdu','decision',array['Attitude positive après une erreur','Réaction constructive après un point perdu','Difficulté à se recentrer']::text[],'Réduire le temps de réaction émotionnelle et repartir avec une consigne utile.','Revenir dans sa routine dès le point suivant dans 8 cas sur 10.',37),
('men-fight','Mental','Maintenir engagement et combativité sur chaque point','decision',array['Combativité sur chaque point','Engagement physique constant','Baisse d’engagement pendant le match']::text[],'Maintenir l’intensité d’engagement du premier au dernier point.','Respecter l’objectif d’engagement sur 8 points sur 10.',38),
('smash-control','Smash','Se placer sous le lob et finir le smash avec contrôle','volleyfinish',array['Jeu de jambes adapté à la trajectoire','Prise de balle tôt','Contrôle de la direction']::text[],'Lire le lob, se déplacer en pas croisés puis ajuster en petits pas pour frapper le smash au-dessus et légèrement devant soi, vers une zone libre.','Réussir 7 smashs sur 10 avec replacement et cible choisie.',39),
('move-direction','Jeu de jambes/déplacements','Enchaîner déplacement, freinage, frappe et replacement','movement',array['Rapidité dans les changements de direction','Qualité de la reprise d’appuis','Replacement rapide']::text[],'Adapter les appuis à la trajectoire, freiner avant la frappe et récupérer vers la zone qui couvre les angles adverses.','Réaliser 7 séquences complètes sur 10 avec frappe équilibrée et replacement.',40),
('match-pattern','Tactique','Construire un point selon le score et la position adverse','decision',array['Construction du point','Choix de zone inadapté','Prise de décision lucide sous pression']::text[],'Lire simultanément la qualité de balle, la position adverse et le score pour choisir entre défense, construction, attaque ou montée.','Prendre une décision tactique adaptée sur 8 points scénarisés sur 10.',41)
) as seed(objective_id,theme,label,profile,criteria,intent,success,display_order)
where coach.role='coach'
on conflict(coach_id,objective_id) do nothing;
comment on table public.coach_session_objectives is 'Catalogue d’objectifs pédagogiques modifiable et privé pour chaque coach, utilisé uniquement pour les cours particuliers Coach In.';